/* ================================================================
   DOOM LIKE — Estética retrô de Doom (1993)
   Preto #0a0a0a, mono Consolas/Courier, vermelho-sangue #c00.
   ================================================================ */

:root {
  --doom-black: #0a0a0a;
  --doom-blood: #c00;
  --doom-blood-bright: #ff2a2a;
  --doom-green: #3cff4a;
  --doom-yellow: #ffd23c;
  --doom-blue: #3c8dff;
  --doom-text: #d0d0d0;
  --doom-muted: #7a7a7a;
  --doom-panel-bg: rgba(10, 10, 10, 0.72);
  --doom-panel-border: #333;
  --font-mono: 'Consolas', 'Courier New', Courier, monospace;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--doom-black);
  color: var(--doom-text);
  font-family: var(--font-mono);
  user-select: none;
  -webkit-user-select: none;
}

/* ---------- Canvas do jogo ---------- */
#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: var(--doom-black);
}

/* ---------- Camada CRT / scanlines ---------- */
#crt-overlay {
  position: fixed;
  inset: 0;
  z-index: 40;
  pointer-events: none;
  background: repeating-linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.06) 0px,
    rgba(255, 255, 255, 0.06) 1px,
    transparent 1px,
    transparent 3px
  );
  opacity: 0.06;
}

/* ---------- Overlays de tela cheia ---------- */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1.2rem;
  text-align: center;
  background: var(--doom-black);
}

.overlay h2 {
  font-size: 3rem;
  letter-spacing: 0.15em;
  color: var(--doom-blood-bright);
  text-shadow: 0 0 18px rgba(255, 0, 0, 0.8), 0 0 40px rgba(255, 0, 0, 0.4);
}

.hidden {
  display: none !important;
}

/* ---------- Menu ---------- */
#menu .title {
  font-size: 5rem;
  font-weight: 900;
  letter-spacing: 0.2em;
  color: var(--doom-blood);
  text-shadow:
    0 0 12px rgba(255, 0, 0, 0.9),
    0 0 40px rgba(255, 0, 0, 0.6),
    0 4px 0 #400000;
  text-transform: uppercase;
}

#menu .subtitle {
  color: var(--doom-muted);
  letter-spacing: 0.3em;
  text-transform: uppercase;
  font-size: 0.9rem;
}

#menu .controls {
  list-style: none;
  color: var(--doom-text);
  font-size: 0.85rem;
  line-height: 1.9;
  text-align: left;
  padding: 1rem 1.5rem;
  background: var(--doom-panel-bg);
  border: 1px solid var(--doom-panel-border);
  box-shadow: inset 0 0 30px rgba(255, 0, 0, 0.08);
}

#menu .controls span {
  display: inline-block;
  min-width: 7.5rem;
  color: var(--doom-blood-bright);
  font-weight: 700;
}

.start-btn {
  font-family: var(--font-mono);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: #fff;
  background: var(--doom-blood);
  border: 2px solid #500;
  padding: 0.8rem 2.5rem;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  text-shadow: 0 0 8px rgba(255, 255, 255, 0.5);
}

.start-btn:hover {
  background: var(--doom-blood-bright);
}

.start-btn:active {
  transform: scale(0.97);
}

/* ---------- HUD ---------- */
#hud {
  position: fixed;
  inset: 0;
  z-index: 20;
  pointer-events: none;
}

#hud-top {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 0.9rem 1.2rem;
}

.stat-panel {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 0.6rem;
  background: var(--doom-panel-bg);
  border: 1px solid var(--doom-panel-border);
}

.stat-label {
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: var(--doom-muted);
}

.stat-value {
  font-size: 1rem;
  font-weight: 700;
  min-width: 2.2rem;
  text-align: right;
  color: #fff;
}

.bar {
  position: relative;
  width: 9rem;
  height: 0.9rem;
  background: #1a1a1a;
  border: 1px solid #000;
  overflow: hidden;
}

.bar-fill {
  position: absolute;
  inset: 0;
  transform-origin: left center;
  transition: width 0.15s linear;
}

/* Barra de vida: gradiente verde -> amarelo -> vermelho (fill por largura) */
.health-fill {
  background: linear-gradient(90deg, var(--doom-green) 0%, var(--doom-yellow) 55%, var(--doom-blood-bright) 100%);
}

/* Barra de armadura: azul */
.armor-fill {
  background: linear-gradient(90deg, #1c4db0 0%, var(--doom-blue) 100%);
}

/* ---------- Mensagens ---------- */
#messages {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding-top: 0.2rem;
  min-height: 2.4rem;
}

#messages .msg {
  font-size: 0.8rem;
  color: var(--doom-text);
  background: rgba(0, 0, 0, 0.55);
  padding: 0.15rem 0.5rem;
  align-self: flex-start;
  animation: msg-fade 3s forwards;
}

@keyframes msg-fade {
  0%   { opacity: 0; transform: translateY(6px); }
  10%  { opacity: 1; transform: translateY(0); }
  80%  { opacity: 1; }
  100% { opacity: 0; }
}

#kills {
  font-size: 0.8rem;
  letter-spacing: 0.1em;
  color: var(--doom-blood-bright);
  background: var(--doom-panel-bg);
  border: 1px solid var(--doom-panel-border);
  padding: 0.35rem 0.7rem;
}

/* ---------- Arma (slot) ---------- */
#weapon-slot {
  position: absolute;
  left: 1rem;
  bottom: 5.2rem;
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

#weapon-name {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: #fff;
}

#weapon-key {
  font-size: 0.75rem;
  color: var(--doom-muted);
  border: 1px solid var(--doom-panel-border);
  padding: 0.15rem 0.4rem;
}

/* ---------- Munição ---------- */
#ammo {
  position: absolute;
  right: 1.2rem;
  bottom: 1rem;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.15rem;
}

#ammo-count {
  font-size: 3.2rem;
  font-weight: 900;
  line-height: 1;
  color: var(--doom-yellow);
  text-shadow: 0 0 10px rgba(255, 210, 60, 0.4);
}

#ammo-type {
  font-size: 0.7rem;
  letter-spacing: 0.25em;
  color: var(--doom-muted);
  text-transform: uppercase;
}

.panel {
  padding: 0.5rem 0.8rem;
  background: var(--doom-panel-bg);
  border: 1px solid var(--doom-panel-border);
}

/* ---------- Minimapa ---------- */
#minimap-panel {
  position: absolute;
  left: 1rem;
  bottom: 1rem;
  width: 200px;
  padding: 0.4rem;
  background: var(--doom-panel-bg);
  border: 1px solid var(--doom-panel-border);
  text-align: center;
}

.minimap-label {
  display: block;
  font-size: 0.6rem;
  letter-spacing: 0.25em;
  color: var(--doom-muted);
  margin-bottom: 0.25rem;
}

#minimap {
  width: 100%;
  height: 150px;
  background: #000;
  border: 1px solid #222;
}

/* ---------- Mira ---------- */
#crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 24px;
  height: 24px;
  transform: translate(-50%, -50%);
}

#crosshair::before,
#crosshair::after {
  content: '';
  position: absolute;
  background: var(--doom-blood-bright);
  box-shadow: 0 0 4px rgba(255, 0, 0, 0.8);
}

/* linha horizontal */
#crosshair::before {
  left: 0;
  top: 50%;
  width: 100%;
  height: 2px;
  transform: translateY(-50%);
}

/* linha vertical */
#crosshair::after {
  top: 0;
  left: 50%;
  height: 100%;
  width: 2px;
  transform: translateX(-50%);
}

/* ---------- Vinheta de dano ---------- */
#damage-vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(
    ellipse at center,
    rgba(255, 0, 0, 0) 40%,
    rgba(255, 0, 0, 0.6) 100%
  );
  opacity: 0;
  transition: opacity 0.2s ease;
}

#damage-vignette.active {
  opacity: 1;
}

/* ---------- Morte ---------- */
#dead {
  background: linear-gradient(180deg, #2a0000 0%, var(--doom-black) 60%);
}

#dead p {
  color: var(--doom-muted);
}

/* ---------- Vitória ---------- */
#complete {
  background: radial-gradient(ellipse at center, #2a1400 0%, var(--doom-black) 70%);
}

#complete h2 {
  color: var(--doom-yellow);
  text-shadow: 0 0 18px rgba(255, 210, 60, 0.8);
}

#complete-stats p {
  font-size: 0.95rem;
  line-height: 2;
  color: var(--doom-text);
}

#complete-stats span {
  color: #fff;
  font-weight: 700;
}

/* ---------- Pausa ---------- */
#paused h2 {
  color: var(--doom-text);
  text-shadow: none;
}

#paused p {
  color: var(--doom-muted);
}

